export const guiEcosystemSignalsByProduct = new Map<string, GuiEcosystemSignalSnapshot[]>();
for (const signal of guiEcosystemSignalSnapshots) {
  const existing = guiEcosystemSignalsByProduct.get(signal.guiId) ?? [];
  existing.push(signal);
  guiEcosystemSignalsByProduct.set(signal.guiId, existing);
}
